def sum(xs: IndexedSeq[Int])(implicit ec: ExecutionContext): Future[Int] =
  if (xs.size < 1024) Future.successful(xs.sum)               // leaf
  else {
    val (l, r) = xs.splitAt(xs.size / 2)
    val fl = sum(l); val fr = sum(r)                          // fork
    fl.zip(fr).map { case (a, b) => a + b }                   // join + combine
  }

